//! Strings, the way the dex tables store them.
//!
//! The tables hold thousands of short strings (every species, move, item,
//! ability and condition name, plus every handler name). Storing them as
//! `&'static str` would cost eight bytes of pointer and length per entry
//! and a NUL per string; the tables instead point into one shared pool
//! with a two byte offset and a one byte length, which is four bytes per
//! entry and no terminators.
//!
//! The pool is generated by `build.rs` from the JSON dumps, and holds every
//! string of every generation exactly once.

/// A reference into the crate's shared string pool.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Str {
    /// Byte offset into the pool.
    pub off: u16,
    /// Length in bytes.
    pub len: u8,
}

impl Str {
    /// The empty string: PS's `''`, `null` or `undefined` for a name field.
    pub const EMPTY: Str = Str { off: 0, len: 0 };

    /// True for [`Str::EMPTY`].
    pub const fn is_empty(self) -> bool {
        self.len == 0
    }

    /// The string this reference points at.
    pub fn as_str(self) -> &'static str {
        let pool: &'static str = POOL;
        &pool[self.off as usize..self.off as usize + self.len as usize]
    }

    /// The string's bytes, for callers that want to compare without UTF-8
    /// ceremony.
    pub fn as_bytes(self) -> &'static [u8] {
        self.as_str().as_bytes()
    }
}

/// Builds a [`Str`] for a pool offset. Used by the generated tables.
pub const fn s(off: u16, len: u8) -> Str {
    Str { off, len }
}

include!(concat!(env!("OUT_DIR"), "/pool.rs"));

/// The longest name any dex entry has, with room to spare. PS's ids are
/// lowercased alphanumerics, so this bounds an id buffer.
pub const ID_CAPACITY: usize = 40;

/// A fixed buffer holding a normalised id, PS's `toID` applied.
#[derive(Clone, Copy, Debug)]
pub struct IdBuf {
    buf: [u8; ID_CAPACITY],
    len: usize,
}

impl IdBuf {
    /// An empty buffer.
    pub const fn new() -> IdBuf {
        IdBuf { buf: [0; ID_CAPACITY], len: 0 }
    }

    /// Normalises a name the way PS's `toID` does: lowercased, with
    /// everything that is not a letter or a digit dropped.
    pub fn from_name(name: &str) -> IdBuf {
        let mut out = IdBuf::new();
        for ch in name.chars() {
            let lower = ch.to_ascii_lowercase();
            if !lower.is_ascii_alphanumeric() {
                continue;
            }
            if out.len < ID_CAPACITY {
                out.buf[out.len] = lower as u8;
                out.len += 1;
            }
        }
        out
    }

    /// The normalised id.
    pub fn as_str(&self) -> &str {
        core::str::from_utf8(&self.buf[..self.len]).unwrap_or("")
    }

    /// True when the buffer is empty.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

impl Default for IdBuf {
    fn default() -> Self {
        IdBuf::new()
    }
}

/// True when `name` normalises to `id` the way PS's `toID` does.
///
/// The dex tables store names, not ids: PS's id for an entry is its name
/// put through `toID` (lowercased, non-alphanumerics dropped), so an id
/// can be checked against a stored name without storing the id as well.
pub fn name_is_id(name: &str, id: &str) -> bool {
    let mut rest = id.as_bytes().iter();
    for ch in name.chars() {
        let lower = ch.to_ascii_lowercase();
        if !lower.is_ascii_alphanumeric() {
            continue;
        }
        match rest.next() {
            Some(&byte) if byte == lower as u8 => {}
            _ => return false,
        }
    }
    rest.next().is_none()
}
